// Command fields lists struct fields declared in test-related Go files, noting
// whether the field carries a struct tag (tag-driven fields may be used only by
// encoding/json and so are not safe to judge by Go references alone).
package main

import (
	"fmt"
	"go/ast"
	"go/parser"
	"go/token"
	"os"
	"path/filepath"
	"strings"
)

func isTestRelated(path string) bool {
	if strings.HasPrefix(path, "vendor/") {
		return false
	}
	base := filepath.Base(path)
	if strings.HasSuffix(base, "_test.go") {
		return true
	}
	for _, d := range []string{
		"cmd/entire/cli/integration_test/",
		"cmd/entire/cli/testutil/",
		"cmd/entire/cli/benchutil/",
		"internal/testdirs/",
		"e2e/",
	} {
		if strings.HasPrefix(path, d) {
			return true
		}
	}
	return base == "testhelpers.go" || base == "testing.go"
}

func main() {
	fset := token.NewFileSet()
	err := filepath.Walk(".", func(path string, info os.FileInfo, err error) error {
		if err != nil {
			return err
		}
		if info.IsDir() {
			if info.Name() == "vendor" || info.Name() == ".git" {
				return filepath.SkipDir
			}
			return nil
		}
		if !strings.HasSuffix(path, ".go") {
			return nil
		}
		rel := strings.TrimPrefix(path, "./")
		if !isTestRelated(rel) {
			return nil
		}
		f, perr := parser.ParseFile(fset, path, nil, parser.SkipObjectResolution)
		if perr != nil {
			return nil
		}
		ast.Inspect(f, func(n ast.Node) bool {
			ts, ok := n.(*ast.TypeSpec)
			if !ok {
				return true
			}
			st, ok := ts.Type.(*ast.StructType)
			if !ok {
				return true
			}
			for _, fld := range st.Fields.List {
				tagged := "notag"
				if fld.Tag != nil {
					tagged = "tagged"
				}
				for _, nm := range fld.Names {
					if nm.Name == "_" {
						continue
					}
					pos := fset.Position(nm.Pos())
					fmt.Printf("%s:%d\t%s\t%s.%s\t%s\n", rel, pos.Line, tagged, ts.Name.Name, nm.Name, nm.Name)
				}
			}
			return true
		})
		return nil
	})
	if err != nil {
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}
}

