// waitForTaskRewindPoint blocks until a task checkpoint with a tool-use ID
// appears in the rewind list, failing the test if none does before the timeout.
func waitForTaskRewindPoint(t *testing.T, dir string, timeout time.Duration) {
	t.Helper()

	deadline := time.Now().Add(timeout)
	for time.Now().Before(deadline) {
		points := entire.RewindList(t, dir)
		for _, point := range points {
			if point.IsLogsOnly || !point.IsTaskCheckpoint {
				continue
			}
			if point.ToolUseID == "" {
				continue
